const express = require("express");
const cors = require("cors");
const { User, Article, Comment } = require("./models");

const SEED_USERNAME = "u1";
const SEED_ARTICLE_SLUG = "a1";
const SEED_COMMENT_BODIES = ["c1", "c2"];

async function seed() {
  const [user] = await User.findOrCreate({
    where: { username: SEED_USERNAME },
    defaults: { username: SEED_USERNAME },
  });

  const [article] = await Article.findOrCreate({
    where: { slug: SEED_ARTICLE_SLUG },
    defaults: { slug: SEED_ARTICLE_SLUG, userId: user.id },
  });

  const count = await Comment.count({ where: { articleId: article.id } });
  if (count > 0) {
    return;
  }

  await Comment.bulkCreate(
    SEED_COMMENT_BODIES.map((body) => ({
      body,
      articleId: article.id,
      userId: user.id,
    })),
  );
}

async function findCommentsByArticleSlug(slug) {
  const article = await Article.findOne({ where: { slug } });
  if (!article) {
    return null;
  }

  return article.getComments({
    include: [{ model: User, as: "author", attributes: ["username"] }],
  });
}

async function getArticleComments(req, res) {
  try {
    const comments = await findCommentsByArticleSlug(req.params.slug);
    if (!comments) {
      return res.status(404).json({ error: "not_found" });
    }

    res.json({ comments });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: "server_error" });
  }
}

function createApp() {
  const app = express();

  app.use(cors());
  app.get("/api/articles/:slug/comments", getArticleComments);

  return app;
}

module.exports = {
  createApp,
  findCommentsByArticleSlug,
  seed,
};

"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const USER_HIDDEN_ATTRIBUTES = ["id", "updatedAt", "createdAt"];
const ARTICLE_HIDDEN_ATTRIBUTES = ["id", "userId"];
const COMMENT_HIDDEN_ATTRIBUTES = ["articleId", "userId"];

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

function toPublicJSON(instance, hiddenAttributes) {
  const data = { ...instance.get() };
  hiddenAttributes.forEach((attribute) => {
    delete data[attribute];
  });
  return data;
}

class User extends Model {
  static associate() {
    this.hasMany(Article, { foreignKey: "userId", onDelete: "CASCADE" });
    this.hasMany(Comment, { foreignKey: "userId" });
  }

  toJSON() {
    return toPublicJSON(this, USER_HIDDEN_ATTRIBUTES);
  }
}

class Article extends Model {
  static associate() {
    this.belongsTo(User, { foreignKey: "userId", as: "author" });
    this.hasMany(Comment, { foreignKey: "articleId", onDelete: "cascade" });
  }

  toJSON() {
    return toPublicJSON(this, ARTICLE_HIDDEN_ATTRIBUTES);
  }
}

class Comment extends Model {
  static associate() {
    this.belongsTo(Article, { foreignKey: "articleId" });
    this.belongsTo(User, { as: "author", foreignKey: "userId" });
  }

  toJSON() {
    return toPublicJSON(this, COMMENT_HIDDEN_ATTRIBUTES);
  }
}

User.init(
  { username: DataTypes.STRING },
  { sequelize, modelName: "User" },
);

Article.init(
  { slug: DataTypes.STRING },
  { sequelize, modelName: "Article" },
);

Comment.init(
  {
    id: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER,
    },
    body: DataTypes.TEXT,
  },
  { sequelize, modelName: "Comment" },
);

User.associate();
Article.associate();
Comment.associate();

module.exports = { sequelize, User, Article, Comment };

const { createApp, seed } = require("./app");
const { sequelize } = require("./models");

const PORT = process.env.PORT || 3001;

async function start() {
  try {
    await sequelize.sync({ alter: true });
    await seed();

    const app = createApp();
    app.listen(PORT, () =>
      console.log(`Server running on http://localhost:${PORT}`),
    );
  } catch (error) {
    console.error("Unable to start:", error);
    process.exit(1);
  }
}

start();

import { useEffect, useState } from "react";
import { getComments } from "./api";

function useComments(slug) {
  const [comments, setComments] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isCurrent = true;

    setError(null);

    getComments(slug)
      .then((nextComments) => {
        if (isCurrent) {
          setComments(nextComments);
        }
      })
      .catch((err) => {
        if (isCurrent) {
          setError(err.message);
          setComments([]);
        }
      });

    return () => {
      isCurrent = false;
    };
  }, [slug]);

  return { comments, error };
}

export default useComments;

import CommentRow from "./CommentRow";
import useComments from "./useComments";

function CommentFeed({ slug }) {
  const { comments, error } = useComments(slug);

  if (error) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

function CommentRow({ body, author, createdAt }) {
  const username = author?.username ?? "unknown";
  const date = createdAt ? new Date(createdAt).toLocaleDateString() : "";

  return (
    <div className="comment">
      <p className="comment-body">{body}</p>
      <p className="comment-meta">
        {username} · {date}
      </p>
    </div>
  );
}

export default CommentRow;

